		const thigh = new Mesh(new CapsuleGeometry(.115, .32, 6, 10), shortMat);
		thigh.position.y = -.22;
		const shin = new Mesh(new CapsuleGeometry(.085, .38, 6, 10), kitMat);
		shin.position.y = -.62;
		const boot = new Mesh(new BoxGeometry(.16, .12, .34), bootMat);
		boot.position.set(0, -.86, .08);
		legPivot.add(thigh, shin, boot);
		player.add(legPivot);
