	steerPivot.add(caliper);
	steerPivot.add(spinPivot);
	parent.add(steerPivot);
	opts.wheelRegister.push(spinPivot);
	if (opts.isFront && opts.frontSteerRegister) opts.frontSteerRegister.push(steerPivot);
