			lerx.position.set(sx * .44, .14, -1.05);
			const intakeBox = new Mesh(new BoxGeometry(.56, .48, 2.35), darkNavalMat);
			intakeBox.position.set(sx * .92, -.08, -.62);
			intakeBox.rotation.z = sx * -.18;
			const intakeHole = new Mesh(new PlaneGeometry(.46, .38), new MeshBasicMaterial({ color: 329744 }));
