			tailShape.lineTo(1.22, 1.72);
			tailShape.lineTo(1.38, 0);
			tailShape.closePath();
			const tailGeo = new ExtrudeGeometry(tailShape, {
				depth: .065,
				bevelEnabled: true,
				bevelThickness: .015,
				bevelSize: .015,
				bevelSegments: 2
			});
			tailGeo.rotateY(-Math.PI / 2);
			const tail = new Mesh(tailGeo, darkNavalMat);
			tail.position.set(sx * .62, .25, 1.95);
			tail.rotation.z = sx * -.34;
			tail.castShadow = true;
