			hStabShape.lineTo(0, .65);
			hStabShape.closePath();
			const hStabGeo = new ExtrudeGeometry(hStabShape, {
				depth: .055,
				bevelEnabled: false
			});
			hStabGeo.rotateX(Math.PI / 2);
			if (sx < 0) hStabGeo.scale(-1, 1, 1);
			const hStab = new Mesh(hStabGeo, navalGrayMat);
			hStab.position.set(sx * .58, -.05, 2.65);
			const missileBodyMat = new MeshStandardMaterial({
				color: 14870768,
				roughness: .28,
				metalness: .55
			});
			const sidewinder = new Mesh(new CylinderGeometry(.048, .048, 2.05, 10), missileBodyMat);
			sidewinder.rotation.x = Math.PI / 2;
			sidewinder.position.set(sx * 4.62, .02, 1.15);
			const pylon = new Mesh(new BoxGeometry(.07, .24, .95), darkNavalMat);
			pylon.position.set(sx * 2.45, -.14, .88);
			const harpoon = new Mesh(new CylinderGeometry(.085, .085, 2.35, 12), darkNavalMat);
			harpoon.rotation.x = Math.PI / 2;
			harpoon.position.set(sx * 2.45, -.31, .82);
			const navLight = new Mesh(new SphereGeometry(.075, 10, 10), new MeshBasicMaterial({ color: sx < 0 ? 16722492 : 2278750 }));
