function computeRamSummaryMetrics(input) {
	const avgBw = (input.bandwidthReadMBs + input.bandwidthWriteMBs) / 2;
	const bwScore = avgBw <= 2500 ? avgBw / 9e3 * 100 : avgBw <= 4500 ? 70 + (avgBw - 2500) / 2e3 * 22 : Math.min(100, 92 + (avgBw - 4500) / 2e3 * 8);
	const latScore = input.latencyNs <= 24 ? Math.min(100, 96 + (24 - Math.max(0, input.latencyNs)) / 14 * 4) : Math.min(96, Math.max(20, 115 - input.latencyNs * 1.4));
	const errorPenalty = input.errorsFound === 0 ? 0 : Math.min(75, 25 + input.errorsFound * 5);
	const overallScore = Math.max(10, Math.min(100, Math.round(bwScore * .6 + latScore * .4 - errorPenalty)));
	if (input.errorsFound === 0 && overallScore >= 60) return {
		overallScore,
		healthGrade: "WZOROWY",
		summaryMessage: "[Podsumowanie] Pamięć RAM w pełni sprawna — 0 błędów we wszystkich 4 testach."
	};
	if (input.errorsFound === 0) return {
		overallScore,
		healthGrade: "DOBRY",
		summaryMessage: "[Podsumowanie] Pamięć stabilna (0 błędów), umiarkowana przepustowość."
	};
	if (input.errorsFound < 5) return {
		overallScore,
		healthGrade: "UWAGA",
		summaryMessage: "[Podsumowanie] Wykryto pojedyncze błędy pamięci — zalecane sprawdzenie kości RAM / profilu XMP."
	};
	return {
		overallScore,
		healthGrade: "KRYTYCZNY",
		summaryMessage: "[Podsumowanie] KRYTYCZNE: Liczne błędy integralności RAM — ryzyko niestabilności systemu!"
	};
}
