	const gpuTested = (ctx.gpu?.avgFps ?? 0) > 0 || (ctx.gpu?.overallScore ?? 0) > 0 || (ctx.game?.avgFps ?? 0) > 0 || (ctx.game?.overallScore ?? 0) > 0 || (ctx.scores?.gpu ?? 0) > 0;
