		const layerCount = this.preset === "ultra" ? 76 : this.preset === "extreme" ? 52 : this.preset === "high" ? 34 : 20;
		const makeHiResTex = (seed) => {
			const c = document.createElement("canvas");
			c.width = texSize;
			c.height = texSize;
			const ctx = c.getContext("2d");
			const g = ctx.createRadialGradient(texSize * .5, texSize * .5, texSize * .06, texSize * .5, texSize * .5, texSize * .5);
			g.addColorStop(0, seed === 0 ? "rgba(6, 182, 212, 0.85)" : "rgba(245, 158, 11, 0.85)");
			g.addColorStop(.55, seed === 0 ? "rgba(37, 99, 235, 0.45)" : "rgba(168, 85, 247, 0.45)");
			g.addColorStop(1, "rgba(6, 9, 17, 0.05)");
			ctx.fillStyle = g;
			ctx.fillRect(0, 0, texSize, texSize);
			ctx.strokeStyle = "rgba(255,255,255,0.22)";
			ctx.lineWidth = Math.max(2, texSize / 256);
			const rings = 18;
			for (let r = 1; r <= rings; r++) {
				ctx.beginPath();
				ctx.arc(texSize / 2, texSize / 2, r / rings * (texSize * .48), 0, Math.PI * 2);
				ctx.stroke();
			}
			for (let a = 0; a < 36; a++) {
				const rad = a / 36 * Math.PI * 2;
				ctx.beginPath();
				ctx.moveTo(texSize / 2, texSize / 2);
				ctx.lineTo(texSize / 2 + Math.cos(rad) * texSize * .49, texSize / 2 + Math.sin(rad) * texSize * .49);
				ctx.stroke();
			}
			const tex = new CanvasTexture(c);
			tex.colorSpace = SRGBColorSpace;
			tex.anisotropy = this.renderer.capabilities.getMaxAnisotropy();
			tex.needsUpdate = true;
			return tex;
		};
		const texA = makeHiResTex(0);
		const texB = makeHiResTex(1);
		const planeGeo = new PlaneGeometry(7.2, 7.2, 8, 8);
		for (let i = 0; i < layerCount; i++) {
			const mesh = new Mesh(planeGeo, new MeshPhysicalMaterial({
				map: i % 2 === 0 ? texA : texB,
				transparent: true,
				opacity: .16,
				roughness: .14,
				metalness: .45,
				clearcoat: 1,
				depthWrite: false,
				side: 2,
				blending: 2
			}));
			mesh.position.z = 3.2 - i * .22;
			mesh.rotation.z = i * .19;
			group.add(mesh);
			this.vramPlanes.push(mesh);
		}
