var PL_MAP = {
	ą: "a",
	ć: "c",
	ę: "e",
	ł: "l",
	ń: "n",
	ó: "o",
	ś: "s",
	ź: "z",
	ż: "z",
	Ą: "A",
	Ć: "C",
	Ę: "E",
	Ł: "L",
	Ń: "N",
	Ó: "O",
	Ś: "S",
	Ź: "Z",
	Ż: "Z",
	"×": "x",
	"—": "-",
	"–": "-",
	"·": "|",
	"≥": ">=",
	"≤": "<=",
	"°": " ",
	"✓": "OK",
	"✔": "OK",
	"⚠️": "UWAGA:",
	"⚠": "UWAGA:"
};
function pdfText(input) {
	return String(input ?? "-").replace(/[ąćęłńóśźżĄĆĘŁŃÓŚŹŻ×—–·≥≤°✓✔⚠]/g, (ch) => PL_MAP[ch] ?? ch).replace(/[^\x20-\x7E]/g, "");
}
function truncateText(str, maxLen) {
	if (str.length <= maxLen) return str;
	return str.slice(0, Math.max(4, maxLen - 3)) + "...";
}
function fitTextToWidth(doc, rawText, maxWidthMm) {
	const clean = pdfText(rawText);
	if (doc.getTextWidth(clean) <= maxWidthMm) return clean;
	let end = clean.length;
	while (end > 3 && doc.getTextWidth(clean.slice(0, end) + "...") > maxWidthMm) end -= 1;
	return clean.slice(0, Math.max(1, end)) + "...";
}
function snapStandardMonitorHz(rawHz) {
	const hz = Number(rawHz || 60);
	if (!Number.isFinite(hz) || hz <= 0) return 60;
	const standards = [
		60,
		75,
		90,
		100,
		120,
		144,
		165,
		170,
		175,
		180,
		200,
		240,
		280,
		300,
		360,
		480
	];
	let best = Math.round(hz);
	let bestDiff = Infinity;
	for (const std of standards) {
		const diff = Math.abs(hz - std);
		if (diff <= Math.max(3.5, std * .025) && diff < bestDiff) {
			bestDiff = diff;
			best = std;
		}
	}
	return best;
}
function cleanGpuModelFromAngle(rawRenderer, rawVendor) {
	const r = String(rawRenderer || "Akcelerator Graficzny 3D").trim();
	const v = String(rawVendor || "").trim();
	const pciMatch = r.match(/\((0x[0-9a-fA-F]+)\)/);
	const pciId = pciMatch ? pciMatch[1] : "";
	let cleanModel = r;
	let backendApi = "Direct3D 11 / WebGL 2.0";
	const angleMatch = r.match(/ANGLE\s*\(\s*([^,]+),\s*([^,]+?)(?:\s*\(0x[0-9a-fA-F]+\))?(?:\s+Direct3D11|\s+Direct3D|\s+Vulkan|\s+OpenGL|,|$)/i);
	if (angleMatch && angleMatch[2]) {
		cleanModel = angleMatch[2].replace(/\s*\(0x[0-9a-fA-F]+\)\s*/i, "").trim();
		if (/Direct3D11/i.test(r)) backendApi = `Direct3D 11${r.match(/vs_5_0\s+ps_5_0/i) ? " (Shader Model 5.0)" : ""}`;
		else if (/Vulkan/i.test(r)) backendApi = "Vulkan API";
		else if (/OpenGL/i.test(r)) backendApi = "OpenGL / ANGLE";
	} else cleanModel = r.replace(/^ANGLE\s*\(/i, "").replace(/\)$/i, "").trim();
	let cleanVendor = v || "Nieznany producent";
	if (/AMD|Radeon/i.test(r) || /AMD/i.test(v)) cleanVendor = "AMD (Advanced Micro Devices)";
	else if (/NVIDIA|GeForce|RTX|GTX/i.test(r) || /NVIDIA/i.test(v)) cleanVendor = "NVIDIA Corporation";
	else if (/Intel|Arc|Iris|UHD/i.test(r) || /Intel/i.test(v)) cleanVendor = "Intel Corporation";
	else if (/Apple/i.test(r) || /Apple/i.test(v)) cleanVendor = "Apple Silicon GPU";
	return {
		cleanModel: pciId ? `${cleanModel} (PCI ID: ${pciId})` : cleanModel,
		cleanVendor,
		backendApi,
		pciId
	};
}
function cleanWebGpuSummaryForPdf(rawSummary) {
	return String(rawSummary || "Aktywny").trim().replace(/^WebGPU:\s*/i, "").replace(/\s*\(MaxBuf\s*\d+\s*MB\)/gi, "").trim() || "Aktywny (Shader FP16 / Compute)";
}
