	doc.setFont("helvetica", "bold");
	doc.setFontSize(7);
	doc.setTextColor(15, 23, 42);
	doc.text(pdfText("NAPRAWA KOMPUTEROW I LAPTOPOW - Rafal Jarosz | NAPRAWAPCLAPTOP.PL | Tel. 786 409 187 | Warszawa, ul. Marymoncka 125 m.109 p.6"), margin, 284);
	doc.setFont("helvetica", "normal");
