	const cpuLines = [["System operacyjny / Arch", specs ? `${specs.os} (${specs.platform})` : "Nieznany"], ["Procesor (CPU)", deep?.cpuModel ? `${deep.cpuModel} (${deep.cpuDetails || `${specs?.cpuCores ?? "-"} watkow logicznych`})` : specs ? `${specs.cpuCores} watkow logicznych (${specs.platform})` : "Nieznany"]];
	if (deep?.motherboard) cpuLines.push(["Plyta glowna / BIOS", `${deep.motherboard} | BIOS: ${deep.bios || "-"}`]);
