function generateBatteryTrendReportPdf(battery, options) {
	const opts = {
		summary: options?.summary ?? true,
		cycleLog: options?.cycleLog ?? true,
		stats: options?.stats ?? true,
		forecast: options?.forecast ?? true
	};
	const doc = new E({
		orientation: "portrait",
		unit: "mm",
		format: "a4"
	});
	const pageW = 210;
	const margin = 14;
	const contentW = 182;
	const nowStr = (/* @__PURE__ */ new Date()).toLocaleString("pl-PL");
	doc.setFillColor(12, 18, 30);
	doc.rect(0, 0, pageW, 34, "F");
	doc.setFillColor(16, 185, 129);
	doc.rect(0, 33, pageW, 1.2, "F");
	doc.setTextColor(255, 255, 255);
	doc.setFont("helvetica", "bold");
	doc.setFontSize(14.5);
	doc.text("SystemPulse Pro - Raport Baterii i Degradacji", margin, 13);
	doc.setFont("helvetica", "normal");
	doc.setFontSize(8.2);
	doc.setTextColor(148, 163, 184);
	doc.text(pdfText("Analiza trendu poboru mocy vs degradacja ogniw (ostatnie 30+ dni)"), margin, 19.8);
	doc.text(pdfText(`Wygenerowano: ${nowStr}`), margin, 26);
	drawRafalJaroszServiceLogoPdf(doc, 130, 4.6, 66, 24);
	let y = 42;
	let sectionIdx = 1;
	if (opts.summary) {
		doc.setFont("helvetica", "bold");
		doc.setFontSize(11);
		doc.setTextColor(15, 23, 42);
		doc.text(pdfText(`${sectionIdx++}. Podsumowanie kondycji ogniw i degradacji`), margin, y);
		y += 6;
		doc.setFont("helvetica", "normal");
		doc.setFontSize(9.5);
		doc.setTextColor(51, 65, 85);
		doc.text(pdfText(`Pojemnosc fabryczna (Design): ${battery.designCapacityMWh} mWh`), margin, y);
		doc.text(pdfText(`Obecna pelna pojemnosc: ${battery.fullChargeCapacityMWh} mWh`), 109, y);
		y += 6;
		doc.text(pdfText(`Stopien zuzycia (Wear Level): ${battery.wearLevelPct}%`), margin, y);
		doc.text(pdfText(`Kondycja ogniw: ${battery.condition}`), 109, y);
		y += 6;
		if (opts.stats) {
			doc.text(pdfText(`Szacowany spadek na cykl: ${battery.avgDegradationPerCycleMWh} mWh / cykl`), margin, y);
			doc.text(pdfText(`Laczna utrata pojemnosci: ${battery.totalCapacityLostMWh} mWh`), 109, y);
			y += 6;
		}
		if (opts.forecast) {
			const projLabel = battery.projectedCyclesTo80Pct !== null ? `~${battery.projectedCyclesTo80Pct} cykli` : "Stabilna";
			doc.text(pdfText(`Prognoza do progu 80%: ${projLabel}`), margin, y);
			y += 6;
		}
		y += 4;
	}
	if (opts.cycleLog) {
		if (y > 250) {
			doc.addPage();
			y = 20;
		}
		doc.setFont("helvetica", "bold");
		doc.setFontSize(11);
		doc.setTextColor(15, 23, 42);
		doc.text(pdfText(`${sectionIdx++}. Rejestr cykli ladowania i spadek pojemnosci (Power Cycle Log)`), margin, y);
		y += 6;
		doc.setFillColor(241, 245, 249);
		doc.rect(margin, y, contentW, 7, "F");
		doc.setFont("helvetica", "bold");
		doc.setFontSize(8.5);
		doc.setTextColor(71, 85, 105);
		doc.text("Data", 17, y + 4.5);
		doc.text("Cykl", 59, y + 4.5);
		doc.text("Zakres (%)", 79, y + 4.5);
		doc.text("Czas (min)", 114, y + 4.5);
		doc.text("Pojemnosc (mWh)", 144, y + 4.5);
		doc.text("Zuzycie (%)", 179, y + 4.5);
		y += 8;
		doc.setFont("helvetica", "normal");
		doc.setFontSize(8.5);
		doc.setTextColor(15, 23, 42);
		const cycles = [...battery.powerCycles].slice(-15);
		for (const c of cycles) {
			if (y > 272) {
				doc.addPage();
				y = 20;
			}
			doc.text(pdfText(c.dateLabel), 17, y + 4);
			doc.text(pdfText(`#${c.cycleNumber}`), 59, y + 4);
			doc.text(pdfText(`${c.startPct}% -> ${c.endPct}%`), 79, y + 4);
			doc.text(pdfText(`${c.durationMin} min`), 114, y + 4);
			doc.text(pdfText(`${c.fullChargeCapacityMWh} mWh`), 144, y + 4);
			doc.text(pdfText(`${c.cumulativeWearPct}%`), 179, y + 4);
			doc.setDrawColor(226, 232, 240);
			doc.setLineWidth(.2);
			doc.line(margin, y + 5.5, 196, y + 5.5);
			y += 7;
		}
	}
	const totalPages = doc.getNumberOfPages();
	for (let p = 1; p <= totalPages; p++) {
		doc.setPage(p);
		doc.setDrawColor(226, 232, 240);
		doc.line(margin, 282.5, 196, 282.5);
		doc.setFont("helvetica", "bold");
		doc.setFontSize(7);
		doc.setTextColor(15, 23, 42);
		doc.text(pdfText("NAPRAWA KOMPUTEROW I LAPTOPOW - Rafal Jarosz | NAPRAWAPCLAPTOP.PL | Tel. 786 409 187 | Warszawa, ul. Marymoncka 125 m.109 p.6"), margin, 286.5);
		doc.setFont("helvetica", "normal");
		doc.setFontSize(6.8);
		doc.setTextColor(100, 116, 139);
		doc.text(pdfText("Copyright (c) Rafal Jarosz - SystemPulse Pro | Raport trendu baterii i degradacji ogniw."), margin, 290.2);
		doc.text(`Strona ${p} / ${totalPages}`, 196, 288.5, { align: "right" });
	}
	doc.save(`systempulse-battery-trend-report-${(/* @__PURE__ */ new Date()).toISOString().slice(0, 10)}.pdf`);
}
