					name: raw.name || "Interfejs",
					description: raw.description || "",
					type,
					status: raw.status === "Up" ? "Up" : "Disconnected",
					linkSpeedMbps: linkMbps,
					maxStandardLabel: cls.standard,
					theoreticalMaxTcpMbps: cls.tcpMax,
					macAddress: raw.macAddress || ""
