	if (n === 35) return "LPDDR5";
	if (n === 26) return "DDR4";
	if (n === 30) return "LPDDR4";
	if (n === 24) return "DDR3";
	if (n === 29) return "LPDDR3";
	if (n === 21) return "DDR2";
