			resolution: `${Math.round(sc.width * (sc.devicePixelRatio || 1))} × ${Math.round(sc.height * (sc.devicePixelRatio || 1))}`,
			dpr: Number((sc.devicePixelRatio || 1).toFixed(2)),
			isPrimary: Boolean(sc.isPrimary),
