	/**
	* Uses File System Access API to pick ANY physical drive/partition (C:, D:, NVMe, USB)
	* and executes a real 16 MB temporary write/read speed probe directly on that disk!
	*/
	async pickAndProbePhysicalDrive() {
		const winAny = window;
		if (typeof winAny.showDirectoryPicker !== "function") return "Przeglądarka nie wspiera File System Access API (użyj Chrome/Edge desktop do testowania dowolnego dysku C:/D:/USB).";
		try {
			const dirHandle = await winAny.showDirectoryPicker({ mode: "readwrite" });
			let entryCount = 0;
			for await (const _ of dirHandle.values()) {
				entryCount++;
				if (entryCount >= 500) break;
			}
			let writeTestedMBs = null;
			let readTestedMBs = null;
			const probeFileName = `.systempulse_probe_${Date.now()}.tmp`;
			try {
				const sizeMB = 16;
				const payload = new Uint8Array(sizeMB * 1024 * 1024);
				for (let i = 0; i < payload.length; i += 4096) payload[i] = i * 31 & 255;
				const fh = await dirHandle.getFileHandle(probeFileName, { create: true });
				const t0 = performance.now();
				const writable = await fh.createWritable();
				await writable.write(payload);
				await writable.close();
				const t1 = performance.now();
				writeTestedMBs = Math.round(sizeMB / Math.max(.005, (t1 - t0) / 1e3) * 10) / 10;
				const r0 = performance.now();
				await (await fh.getFile()).arrayBuffer();
				const r1 = performance.now();
				readTestedMBs = Math.round(sizeMB / Math.max(.005, (r1 - r0) / 1e3) * 10) / 10;
				await dirHandle.removeEntry(probeFileName);
			} catch {}
			const info = {
				name: dirHandle.name || "Wybrany dysk",
				entryCount,
				writeTestedMBs,
				readTestedMBs,
				testedAt: Date.now()
			};
			this.mountedVolumes = [info, ...this.mountedVolumes.filter((v) => v.name !== info.name)].slice(0, 8);
			return writeTestedMBs !== null ? `Przetestowano dysk „${info.name}”: zapis ${writeTestedMBs} MB/s, odczyt ${readTestedMBs} MB/s.` : `Zamontowano wolumin „${info.name}” (${entryCount} elementów, tryb tylko do odczytu).`;
		} catch (err) {
			return err instanceof Error ? `Anulowano wybór dysku: ${err.message}` : "Anulowano wybór dysku.";
		}
	}
