	const cutoff = (sorted.length > 0 ? sorted[sorted.length - 1].timestamp : Date.now()) - windowSeconds * 1e3;
	const recent = sorted.filter((pt) => pt.timestamp >= cutoff);
	const rows = recent.length > 0 ? recent : sorted.slice(-24);
