function renderHardwareHealthD3Chart(container, cards) {
	container.innerHTML = "";
	if (!cards || cards.length === 0) {
		container.innerHTML = `
      <div style="height:210px;display:flex;align-items:center;justify-content:center;color:var(--text-muted);font-size:12px;">
        Trwa automatyczne skanowanie 12 podzespołów sprzętowych...
      </div>`;
		return;
	}
	const width = Math.max(420, container.clientWidth || 760);
	const height = 215;
	const margin = {
		top: 22,
		right: 18,
		bottom: 44,
		left: 38
	};
	const innerW = width - margin.left - margin.right;
	const innerH = height - margin.top - margin.bottom;
	const g = select(container).append("svg").attr("viewBox", `0 0 ${width} ${height}`).style("width", "100%").style("height", `${height}px`).style("display", "block").append("g").attr("transform", `translate(${margin.left},${margin.top})`);
	const x = band().domain(cards.map((c) => c.category)).range([0, innerW]).padding(.28);
	const y = linear().domain([0, 100]).range([innerH, 0]);
	g.append("g").selectAll("line").data([
		0,
		25,
		50,
		75,
		100
	]).enter().append("line").attr("x1", 0).attr("x2", innerW).attr("y1", (v) => y(v)).attr("y2", (v) => y(v)).attr("stroke", "rgba(148,163,184,0.14)");
	const getColor = (c) => c.score >= 90 ? "#10b981" : c.score >= 75 ? "#06b6d4" : c.score >= 55 ? "#f59e0b" : "#ef4444";
	g.selectAll(".hw-bar-bg").data(cards).enter().append("rect").attr("x", (c) => x(c.category) ?? 0).attr("y", 0).attr("width", x.bandwidth()).attr("height", innerH).attr("rx", 5).attr("fill", "rgba(30,41,59,0.45)");
	g.selectAll(".hw-bar").data(cards).enter().append("rect").attr("x", (c) => x(c.category) ?? 0).attr("y", (c) => y(c.score)).attr("width", x.bandwidth()).attr("height", (c) => Math.max(3, innerH - y(c.score))).attr("rx", 5).attr("fill", (c) => getColor(c)).attr("fill-opacity", .9).append("title").text((c) => `${c.title}: ${c.score}/100 (${c.headline})`);
	g.selectAll(".hw-val").data(cards).enter().append("text").attr("x", (c) => (x(c.category) ?? 0) + x.bandwidth() / 2).attr("y", (c) => y(c.score) - 5).attr("text-anchor", "middle").attr("fill", "#f8fafc").attr("font-size", 10).attr("font-family", "JetBrains Mono, monospace").attr("font-weight", 700).text((c) => `${c.score}%`);
	g.append("g").attr("transform", `translate(0,${innerH})`).call(axisBottom(x)).call((axis) => axis.selectAll("path, line").attr("stroke", "rgba(148,163,184,0.25)")).call((axis) => axis.selectAll("text").attr("fill", "#cbd5e1").attr("font-size", 9.5).attr("font-family", "JetBrains Mono, monospace").attr("transform", "rotate(-20)").style("text-anchor", "end"));
	g.append("g").call(axisLeft(y).ticks(4).tickFormat((v) => `${v}%`)).call((axis) => axis.selectAll("path, line").attr("stroke", "rgba(148,163,184,0.25)")).call((axis) => axis.selectAll("text").attr("fill", "#94a3b8").attr("font-size", 9.5).attr("font-family", "JetBrains Mono, monospace"));
}
