	async runFullSystemSuite() {
		if (this.fullSuiteRunning) return;
		this.fullSuiteRunning = true;
		this.beginStressSession();
		this.syncTopbarCta();
		try {
			this.fullSuiteStep = "Krok 1/5: Test procesora CPU (Single/Multi-Core, GZIP, SHA-256)...";
			this.setModule("dashboard");
			this.renderWorkspace();
			this.cpuState = await cpuTestService.runFullBenchmark((res) => {
				this.cpuState = res;
				if (this.activeModule === "dashboard") this.renderWorkspace();
			});
			await this.recordLog("CPU", "OK", "Zakończono test CPU", "Multi-Core", `${this.cpuState.multiCoreScore} pkt`, `Single-Core: ${this.cpuState.singleCoreScore}, GZIP: ${this.cpuState.compressionMBs} MB/s, SHA-256: ${this.cpuState.cryptoSha256MBs} MB/s`);
			this.fullSuiteStep = "Krok 2/5: Test pamięci RAM (128 MB wzorce bitowe, PRNG, przepustowość)...";
			if (this.activeModule === "dashboard") this.renderWorkspace();
			this.ramState = await ramTestService.runTest(128, (res) => {
				this.ramState = res;
				if (this.activeModule === "dashboard") this.renderWorkspace();
			});
			await this.recordLog("RAM", this.ramState.errorsFound === 0 ? "OK" : "ERROR", "Zakończono test RAM", "Przepustowość / Błędy", `${this.ramState.bandwidthReadMBs} MB/s | ${this.ramState.errorsFound} błędów`, `Zapis: ${this.ramState.bandwidthWriteMBs} MB/s, Opóźnienie: ${this.ramState.latencyNs} ns, Ocena: ${this.ramState.healthGrade}`);
			this.fullSuiteStep = "Krok 3/5: Test dysku SSD/HDD (OPFS/IDB I/O + diagnostyka SMART)...";
			if (this.activeModule === "dashboard") this.renderWorkspace();
			this.diskState = await diskTestService.runTest((res) => {
				this.diskState = res;
				if (this.activeModule === "dashboard") this.renderWorkspace();
			});
			await this.recordLog("DISK", this.diskState.smartStatus === "ZDROWY" ? "OK" : "WARN", "Zakończono test dysku i SMART", "Odczyt Seq / SMART", `${this.diskState.seqReadMBs} MB/s | ${this.diskState.smartStatus}`, `Zapis: ${this.diskState.seqWriteMBs} MB/s, 4K: ${this.diskState.rand4kIops} IOPS, Dostęp: ${this.diskState.accessTimeAvgMs} ms`);
			this.fullSuiteStep = "Krok 4/5: Test sieci i opóźnień (Ping, Jitter, utrata pakietów)...";
			if (this.activeModule === "dashboard") this.renderWorkspace();
			this.networkState = await networkTestService.runTest((res) => {
				this.networkState = res;
				if (this.activeModule === "dashboard") this.renderWorkspace();
			});
			await this.recordLog("NETWORK", this.networkState.qualityGrade === "WZOROWA" || this.networkState.qualityGrade === "DOBRA" ? "OK" : "WARN", "Zakończono test sieci", "Ping / Jitter", `${this.networkState.pingAvgMs} ms / ${this.networkState.jitterMs} ms`, `Utrata: ${this.networkState.packetLossPct}%, Transfer: ${this.networkState.downloadEstMbps} Mbps, Ocena: ${this.networkState.qualityGrade}`);
			this.fullSuiteStep = "Krok 5/5: Test karty graficznej WebGL 3D bez limitu FPS (4 s)...";
			this.setModule("gpu");
			await new Promise((r) => setTimeout(r, 150));
			this.gpuState = await gpuStressEngine.runTimedBenchmark(4200, (m) => {
				this.gpuState = m;
				this.patchGpuLive();
			});
			await this.recordLog("GPU", this.gpuState.verdict === "STABILNY" ? "OK" : "WARN", "Zakończono stres-test GPU 3D", "Śr. / Max FPS", `${this.gpuState.avgFps} / ${this.gpuState.maxFps} FPS`, `Tryb: ${this.gpuState.fpsMode}, Preset: ${this.gpuState.preset}, 1% Low: ${this.gpuState.low1PctFps} FPS, Stabilność: ${this.gpuState.stabilityPct}%`);
			await this.runAuto12ComponentScan();
			this.lastSuiteTimestamp = Date.now();
			this.fullSuiteStep = "Kompleksowa diagnostyka od A do Z zakończona i zapisana w IndexedDB.";
			const scores = this.getSuiteScores();
			const combinedStab = Number(((this.cpuState.stabilityPct + this.gpuState.stabilityPct) / 2).toFixed(1));
			this.finalizeStressSession("Pełna Diagnostyka", combinedStab, `Indeks ${scores.overall}/100 (${scores.grade}) · CPU ${this.cpuState.multiCoreScore} pkt · GPU ${this.gpuState.avgFps} FPS`);
			this.setModule("dashboard");
		} finally {
			this.fullSuiteRunning = false;
			this.syncTopbarCta();
			this.renderWorkspace();
		}
	}
