			extraVisualHtml = `<div class="font-mono" style="margin-top:6px;font-size:11.5px;color:var(--text-secondary);">Faza CPU: <strong class="status-cyan">${esc(c.phase || "Obciążenie wielowątkowe")}</strong></div>`;
